import type { Metadata } from "next";
import { absoluteUrl, siteUrl } from "./site";
import { profile, sameAs } from "@/content/profile";
import { skillGroups } from "@/content/skills";
import type { Project } from "@/content/projects";

/** Generated by app/opengraph-image.tsx; resolved against metadataBase (NEXT_PUBLIC_SITE_URL). */
export const shareImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${profile.brand}: ${profile.name}, Full Stack Engineer and AI Builder`,
};

type PageMetaInput = { title: string; description: string; path: string };

/** Per-route metadata with a canonical URL built from the central site config. */
export function pageMetadata({ title, description, path }: PageMetaInput): Metadata {
  const url = absoluteUrl(path);
  return {
    title,
    description,
    alternates: { canonical: url },
    openGraph: { title, description, url, type: "website", siteName: profile.brand, images: [shareImage] },
    twitter: { card: "summary_large_image", title, description, images: [shareImage.url] },
  };
}

export const personId = `${siteUrl}/#person`;
export const websiteId = `${siteUrl}/#website`;

export function personJsonLd() {
  return {
    "@type": "Person",
    "@id": personId,
    name: profile.name,
    jobTitle: profile.role,
    description: profile.summary,
    url: absoluteUrl("/"),
    sameAs,
    knowsAbout: skillGroups.flatMap((g) => g.skills),
  };
}

export function websiteJsonLd() {
  return {
    "@type": "WebSite",
    "@id": websiteId,
    name: `${profile.brand} | ${profile.name}`,
    url: absoluteUrl("/"),
    author: { "@id": personId },
    inLanguage: "en",
  };
}

export function breadcrumbJsonLd(items: { name: string; path: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((item, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: item.name,
      item: absoluteUrl(item.path),
    })),
  };
}

export function projectJsonLd(project: Project) {
  const base = {
    "@context": "https://schema.org",
    name: project.title,
    description: project.oneLiner,
    url: absoluteUrl(`/projects/${project.slug}`),
    author: { "@type": "Person", "@id": personId, name: profile.name },
    keywords: project.stack.join(", "),
    creativeWorkStatus: project.status,
  };
  // SoftwareSourceCode only when there is real, public source to point at.
  return project.links.source
    ? { ...base, "@type": "SoftwareSourceCode", codeRepository: project.links.source }
    : { ...base, "@type": "CreativeWork" };
}
